import React from "react";
import { useState, useEffect } from "react";

// import "font-awesome/css/font-awesome.min.css";
import Alerts from "../htmlcomponents/Alerts";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import api from "../api/Webcall";
import Spinner from "../htmlcomponents/Spinner";

import { GetAllScreenList } from "../utilities/getallscreen";
import { GetAllStageList } from "../utilities/getallstage";
import { GetBranchList } from "../utilities/getbranchlist";
import { GetStageFlowMapping } from "../utilities/getStageFlowMapping";
import { GetStageFlowBranchMapping } from "../utilities/getStageFlowBranchMapping";

import Table from "react-bootstrap/Table";
import { Scrollbar } from "react-scrollbars-custom";
import { toast } from 'react-toastify';

import Button from "react-bootstrap/Button";
import Modal from "react-bootstrap/Modal";

import {
  generateUUID,
  compressBase64,
  decompressBase64,
} from "../utilities/utils";

import appsettings from "../../appsettings.json"

const apiendpoints = appsettings.ApiEndpoints;

const CompanyId = localStorage.getItem("CompanyId")


const schema = yup.object().shape({
  cmbScreenId: yup.string().required("Pls select the screen"),
});

//rfce - command
function CrossBranchStageMapping() {
  // Const & Var

  const [Taskresbody, settasklistresbody] = useState([]);
  const [alert, setAlert] = useState("");
  const [isLoading, setLoanding] = useState(false);
  const [childelms, setscrchildelms] = useState([]);
  const [Screenid, setScreenid] = useState(0);
  const [screenfilterlist, setscreenfilterlist] = useState([]);
  const [StgList, setStgList] = useState([]);
  const [BrList, setBrList] = useState([]);
  const [StgflowList, setStgflowList] = useState([]);
  const [StgflowBrList, setStgflowBrList] = useState([]);
  
  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm({
    resolver: yupResolver(schema),
  });



  // General Function

  const FetchAllScreenList = async () => {
    const ScreenListResponse = await GetAllScreenList(); 
    setscreenfilterlist(ScreenListResponse.body.Screens.filter((res) => res.IsActive==true));
  };


  
  const FetchAllStageList = async (ScrId) => {
    const StageList = await GetAllStageList(ScrId);
    setStgList(StageList.body.Stages);
  };

  const FetchAllBranchList = async () => {
    const BranchList = await GetBranchList();
    console.log(BranchList)
    setBrList(BranchList.body.Branches);
  };

  const FetchStageFlowMapping = async (ScrId) => {
    const StageFlowList = await GetStageFlowMapping(ScrId);   
    setStgflowList(StageFlowList.body.stgflowmap);
  };


  const FetchStageFlowBranchMapping = async (MapId) => {
    const StageFlowBrList = await GetStageFlowBranchMapping(MapId);
    console.log(StageFlowBrList);
    setStgflowBrList(StageFlowBrList.body.stgflowbranchmap);
  };




  
  // Useeffect

  useEffect(() => {
   
    FetchAllScreenList(); 
    FetchAllBranchList();  
  }, []);

 

  // Event function start


  const ScreenOnChange = (e) => {  
    
       setScreenid(e.target.value);
       FetchAllStageList(e.target.value);
       FetchStageFlowMapping(e.target.value);
       ResetScreenValue(); 

  };



  const onSubmitHandler = async (data) => {
    
     let Screenid = data.cmbScreenId;
     let action = "A" ;
     let  StageTo = [data.cmbStageTo]; 

    let frmData = { txtFlag:action, cmbScrId:Screenid,cmbStageFrom:data.cmbStageFrom,cmbStageTo:StageTo};

    const updstgflmap = apiendpoints.updstgflmap;

    console.log(frmData);


    setLoanding(true);

    //e.preventDefault();
    /* Header */
    const convID = generateUUID();
    const frmHdr = {
      convid: convID,
      tag: "updstgflmap",
      orgid: "",
      vendid: "0",
    };

    const token = localStorage.getItem("token");
    const reqHdr = { headers: { Authorization: `Bearer ${token}` } };
    const reqdata = { hdr: frmHdr, body: frmData };

    const CoreUrl = process.env.REACT_APP_FinXCoreUrl;

    console.log(reqdata);

    try {
      //
      const response = await api.post(
        updstgflmap,
        compressBase64(reqdata),
        reqHdr
      );

      const strResponse = JSON.parse(decompressBase64(response.data));

      console.log(strResponse);

      if (strResponse.hdr.rst == "FAILED" || strResponse.hdr.rst == "ERROR") {
        ShowAlert("Error", JSON.stringify(strResponse.fdr[0].rstmsg));
        setLoanding(false);
      } else {
        setTimeout(() => {
          console.log(strResponse.fdr);
          ShowAlert("Success", JSON.stringify(strResponse.fdr[0].rstmsg));
          toast.success("Successfully updated");
          setTimeout(() => {
            setAlert({
              AlertType: "null",
              message: "null",
            });
          }, 600);
          ResetScreenValue();
         
          setLoanding(false);
        }, 300);
      }
    } catch (err) {
      console.log(err.message);
      toast.error("Unable to process request");
      ShowAlert("Error", "Unable to process request");
      setLoanding(false);
    }
    FetchStageFlowMapping(Screenid);
  }


  //---------------onSubmitHandler end-----popup submit start-


  const onPopupSubmitHandler = async (data,e) => {
    
    e.preventDefault(); 

    let Screenid = data.cmbScreenId;
    let action = "A" ;
    let  BranchFrom = [data.cmbBranchFrom]; 
    let  BranchTo =null;
    if (data.cmbBranchTo!='0')
        BranchTo =data.cmbBranchTo
    




   let frmData = { txtFlag:action,txtStgFlowMapId: data.txtStgFlowMapId,cmbBranchFrom:BranchFrom,cmbBranchTo:BranchTo};

   const updstgflbrchmap = apiendpoints.updstgflbrchmap;

   console.log(frmData);


   setLoanding(true);

   //e.preventDefault();
   /* Header */
   const convID = generateUUID();
   const frmHdr = {
     convid: convID,
     tag: "updstgflmap",
     orgid: "",
     vendid: "0",
   };

   const token = localStorage.getItem("token");
   const reqHdr = { headers: { Authorization: `Bearer ${token}` } };
   const reqdata = { hdr: frmHdr, body: frmData };

   const CoreUrl = process.env.REACT_APP_FinXCoreUrl;

   console.log(reqdata);

   try {
     //
     const response = await api.post(
      updstgflbrchmap,
       compressBase64(reqdata),
       reqHdr
     );

     const strResponse = JSON.parse(decompressBase64(response.data));

     console.log(strResponse);

     if (strResponse.hdr.rst == "FAILED" || strResponse.hdr.rst == "ERROR") {
       ShowAlert("Error", JSON.stringify(strResponse.fdr[0].rstmsg));
       setLoanding(false);
     } else {
       setTimeout(() => {
         console.log(strResponse.fdr);
         ShowAlert("Success", JSON.stringify(strResponse.fdr[0].rstmsg));
         toast.success("Successfully updated");
         setTimeout(() => {
           setAlert({
             AlertType: "null",
             message: "null",
           });
         }, 600);
         //ResetScreenValue();        
         setLoanding(false);
       }, 300);
     }
   } catch (err) {
     console.log(err.message);
     toast.error("Unable to process request");
     ShowAlert("Error", "Unable to process request");
     setLoanding(false);
   }
   FetchStageFlowBranchMapping(data.txtStgFlowMapId)
 }


  
  const [gridshow, setgridShow] = useState(false);

  const gridhandleClose = () => setgridShow(false);
  const gridhandleShow = () => setgridShow(true);

  
  function SetScreenValue(rowval)  
  {
    reset({ txtTaskElmentId: rowval.tleid, txtHeader: rowval.hdr, txtOrder : rowval.ord,
      cmbStageTypeId : rowval.elmid   }) 
  }

  
  function BranchMappingPopup(x)  
  {
    gridhandleShow();
    reset({ txtStgFlowMapId: x.mapid})       
    FetchStageFlowBranchMapping(x.mapid)

  }
  function ResetScreenValue()  
  {
    
    reset({ txtStgFlowMapId: "",cmbStageFrom:"",cmbStageTo:""})    

  }

  function EditScreenValue(x)  
  {
    reset({ txtStgFlowMapId: x.mapid,cmbStageFrom:x.stgfr,cmbStageTo:x.stgto})  
  }

  const DeleteScreenValue = async (data) => {

   
     let action = "D" ;
     let  StageTo = [data.stgto]; 

    let frmData = { txtFlag:action, cmbScrId:Screenid,cmbStageFrom:data.stgfr,cmbStageTo:StageTo};

    const updstgflmap = apiendpoints.updstgflmap;

    console.log(frmData);


    setLoanding(true);

    //e.preventDefault();
    /* Header */
    const convID = generateUUID();
    const frmHdr = {
      convid: convID,
      tag: "updstgflmap",
      orgid: "",
      vendid: "0",
    };

    const token = localStorage.getItem("token");
    const reqHdr = { headers: { Authorization: `Bearer ${token}` } };
    const reqdata = { hdr: frmHdr, body: frmData };

    const CoreUrl = process.env.REACT_APP_FinXCoreUrl;

    console.log(reqdata);

    try {
      //
      const response = await api.post(
        updstgflmap,
        compressBase64(reqdata),
        reqHdr
      );

      const strResponse = JSON.parse(decompressBase64(response.data));

      console.log(strResponse);

      if (strResponse.hdr.rst == "FAILED" || strResponse.hdr.rst == "ERROR") {
        ShowAlert("Error", JSON.stringify(strResponse.fdr[0].rstmsg));
        setLoanding(false);
      } else {
        setTimeout(() => {
          console.log(strResponse.fdr);
          ShowAlert("Success", JSON.stringify(strResponse.fdr[0].rstmsg));
          toast.success("Successfully updated");
          setTimeout(() => {
            setAlert({
              AlertType: "null",
              message: "null",
            });
          }, 600);
          ResetScreenValue();
          FetchStageFlowMapping(Screenid);
          setLoanding(false);
        }, 300);
      }
    } catch (err) {
      console.log(err.message);
      toast.error("Unable to process request");
      ShowAlert("Error", "Unable to process request");
      setLoanding(false);
    }
   
  }

  
  // Event Function End

  // Main Function

  const ShowAlert = (alertType, message) => {
    setAlert({
      AlertType: alertType,
      message: message,
    });
  };

  try {
    return (
      <>
        <section className="vh-100">
          <div className="container h-100">
            {/* <div className="row d-flex justify-content-center align-items-center h-100">
                  <div className="col-lg-12 col-xl-11"> */}
            <div className="card text-black" style={{ borderRadius: "25px" }}>
              <div className="card-header">
                <strong className="card-title">Cross Branch Stage Mapping</strong>
              </div>
              <div className="card-body p-md-5">
                {isLoading ? <Spinner></Spinner> : ""}
                <Alerts alert={alert} />

                <form
                  onSubmit={handleSubmit(onSubmitHandler)}
                  autocomplete="off"
                >
                 <div className="row">
                 <div className="col-sm">
                                    <div className="mb-3">
                                        <label htmlFor="cmbScreenId" className="form-label">Screen</label>
                                        <select {...register("cmbScreenId")}  className="form-control"  onChange={ScreenOnChange}> 
                                            <option value="0">- Select -</option>
                                            {  //Combo Data binding
                                                        
                                                        screenfilterlist.map((res) => 
                                                        (<option key={res.ScreenId} value={res.ScreenId}>{res.ScrName}</option>))
                                            }
                                            
                                        </select>
                                        <p>{errors.cmbScreenId?.message}</p>
                                    </div>
                                </div>
                 <div className="col-sm">
                 <div className="mb-3">
                        <label htmlFor="txtStgFlowMapId" className="form-label">
                          {" "}
                         Cross branch MapId
                        </label>
                        <input
                          {...register("txtStgFlowMapId")}
                          type="text"
                          className="form-control"
                          disabled="disabled"
                          readonly="readonly"
                        />
                      </div>
                 </div>
                 </div>

                           

                  <div className="row">
                    <div className="col-sm">
                      <div className="mb-3">
                        <label htmlFor="cmbStageFrom" className="form-label">
                          {" "}
                          Stage From
                        </label>
                        <select {...register("cmbStageFrom")}  className="form-control"  onChange={""}> 
                                            <option value="0">- Select -</option>
                                            {                                                         
                                                        StgList.map((res) => (
                                                          <option key={res.StageId} value={res.StageId}>
                                                            {res.StageName}</option>))
                                            }
                                        </select>                        
                      </div>
                    </div>
                    <div className="col-sm">
                      <div className="mb-3">
                        <label htmlFor="cmbStageTo" className="form-label">
                          {" "}
                          Stage To
                        </label>
                        <select {...register("cmbStageTo")}  className="form-control"  onChange={""}> 
                                            <option value="0">- Select -</option>
                                            {                                                         
                                                        StgList.map((res) => (
                                                          <option key={res.StageId} value={res.StageId}>
                                                            {res.StageName}</option>))
                                            }
                                        </select>                      
                      </div>
                    </div>
                  </div>

                 
                
                  
                  
                  <button type="submit" className="btn btn-primary">
                    Submit
                  </button>
                </form>
              </div>

              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th>Mapp Id</th>       
                    <th>Stage Id</th>                  
                    <th>Stage From</th>
                    <th>Stage Id</th>    
                    <th>Stage To</th>                    
                    <th>
                      <button
                        className="btn btn-success"
                        onClick={() => {
                          ResetScreenValue();
                        }}
                      >
                        {" "}
                        <i className="bi bi-table"></i> Add{" "}
                      </button>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {StgflowList && StgflowList.map((x) => {
                    return (
                      <tr>
                        <td>{x.mapid}</td>
                        <td>{x.stgfr}</td>
                        <td>{x.stgfrna}</td>
                        <td>{x.stgto}</td>
                        <td>{x.stgtona}</td>
                       
                        <td>
                          <button
                            className="btn btn-primary"
                            onClick={() => {
                              EditScreenValue(x);
                            }}
                          >
                            {" "}
                            <i className="bi bi-pen"></i> Edit
                          </button>
                        </td>
                        <td> 
                            
                            <button className="btn btn-danger"   onClick={() => {   
                                        DeleteScreenValue(x);                                                 
                                        }} >  <i class="bi bi-trash"></i> </button></td>
                       
                           <td>
                          <button
                            className="btn btn-primary"
                            onClick={() => {
                              BranchMappingPopup(x);
                            }}
                          >
                            {" "}
                            <i className="bi bi-table"></i> Add Branch{" "}
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
            </div>
          </div>
        </section>

        
        <Modal
          show={gridshow}
          onHide={gridhandleClose}
          size="xl"
          aria-labelledby="contained-modal-title-vcenter"
          centered
        >
          <Modal.Header closeButton>
            <Modal.Title>Stage Flow Branch Mapping</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <form    onSubmit={handleSubmit(onPopupSubmitHandler)}
                              autocomplete="off" >
              <div className="row">
                <div className="col-sm">
                  <div className="mb-3">

                  <label htmlFor="cmbBranchFrom" className="form-label">Branch From</label>
                   <select {...register("cmbBranchFrom")}  className="form-control"> 
                                            <option value="0">- Select -</option>
                                            {  //Combo Data binding                                                        
                                                        BrList.map((res) => 
                                                        (<option key={res.BranchId} value={res.BranchId}>{res.Name}</option>))
                                            }
                                            
                    </select>

                    
                  </div>
                </div>
                <div className="col-sm">
                  <div className="mb-3">
                  <label htmlFor="cmbBranchTo" className="form-label">Branch To</label>
                   <select {...register("cmbBranchTo")}  className="form-control"> 
                                            <option value="0">- Select -</option>
                                            {  //Combo Data binding
                                                    BrList.map((res) => 
                                                      (<option key={res.BranchId} value={res.BranchId}>{res.Name}</option>))
                                            }
                                            
                    </select>
                  </div>
                </div>
                 

                 
              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th>ID</th>    
                    <th>Branch From</th>
                    <th>Branch To</th>                    
                    
                  </tr>
                </thead>
                <tbody>
                  {StgflowBrList && StgflowBrList.map((x) => {
                    return (
                      <tr>
                        <td>{x.id}</td>
                        <td>{x.frbranchna}</td>
                        <td>{x.tobranchna}</td>
                        {/* <td>{ childelms.filter((res) => res.k==x.elmid)}</td> */}
                        <td>{x.ord}</td>

                         
                       
                           <td>
                          <button
                            className="btn btn-primary"
                            onClick={() => {
                              SetScreenValue(x);
                            }}
                          >
                            {" "}
                            <i className="bi bi-pen"></i> Edit
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
               
              </div>

              <Modal.Footer>
                <Button variant="secondary" onClick={gridhandleClose}>
                  Close
                </Button>
                <Button type="submit" variant="secondary">
                  Update
                </Button>
              </Modal.Footer>
            </form>
          </Modal.Body>
        </Modal>
      </>
    );
  } catch (error) {
    console.log(error.message);
  }
}

export default CrossBranchStageMapping;